# Find connected components of 0s in the demo input
from collections import deque

def find_zero_components(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    components = []

    def bfs(start):
        comp = [start]
        q = deque([start])
        visited[start[0]][start[1]] = True
        while q:
            r, c = q.popleft()
            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc] and grid[nr][nc] == 0:
                        visited[nr][nc] = True
                        comp.append((nr, nc))
                        q.append((nr, nc))
        return comp

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 0 and not visited[i][j]:
                comp = bfs((i, j))
                components.append(comp)

    return components

