# Build connectivity graph considering both orthogonal and diagonal moves for 0s
def get_neighbors(grid, r, c, include_diag=True):
    rows, cols = len(grid), len(grid[0])
    neighbors = []

    # Orthogonal
    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
            neighbors.append((nr, nc))

    # Diagonal
    if include_diag:
        for dr, dc in [(1,1), (1,-1), (-1,1), (-1,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                neighbors.append((nr, nc))

    return neighbors

# Find which component contains each existing 3
def zero_component_of(pos, grid):
    """Find which zero component a position belongs to, or None if not 0"""
    i, j = pos
    if grid[i][j] != 0:
        return None
    visited = [[False]*len(grid[0]) for _ in range(len(grid))]

    def bfs_from(start):
        q = [start]
        visited[start[0]][start[1]] = True
        result = []
        while q:
            r, c = q.pop(0)
            result.append((r, c))
            for nr, nc in get_neighbors(grid, r, c):
                if not visited[nr][nc]:
                    visited[nr][nc] = True
                    q.append((nr, nc))
        return result

    comp = bfs_from(pos)
    return set(comp)

