def dist_to_threes(pos, grid):
    """Find shortest distance from position to any existing 3 using only orthogonal moves through 0s"""
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    # Find initial set: all zeros that are diagonally adjacent to a 3
    start_set = []
    for i in range(rows):
