                for dr, dc in [(1,1), (1,-1), (-1,1), (-1,-1)]:
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < rows and 0 <= nj < cols and grid[ni][nj] == 0:
                        start_set.append((ni, nj))

    # BFS from start_set
    q = list(start_set)
    distances = {p: 0 for p in start_set}
    idx = 0
    while idx < len(q):
        r, c = q[idx]
        idx += 1
