from collections import deque
def find_reachable(start, adjacency):
    visited = set([start])
    queue = deque([start])
    while queue:
        curr = queue.popleft()
        for neighbor in adjacency[curr]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return visited

