from collections import deque

def find_reachable_from(start_nodes, adjacency):
    visited = set()
    queue = list(start_nodes)
    while queue:
        curr = queue.pop(0)
        if curr in visited:
            continue
        visited.add(curr)
        for neighbor in adjacency[curr]:
            if neighbor not in visited:
                queue.append(neighbor)
    return visited

