                                nnr, nnc = r + odr, c + odc
                                if 0 <= nnr < rows and 0 <= nnc < cols and grid[nnr][nnc] == 0:
                                    new_added.add((nnr, nnc))

                        r += dr
                        c += dc

            if not new_added:
                break
            filled.update(new_added)
        return filled

    results = {}
    results['diag_step'] = diag_step_only()
    results['chain_diag'] = chain_diag_until_nonzero()
    results['diag_orth'] = diag_then_orth_each_step()

    matches = {name: result == target_set for name, result in results.items()}

    for name, matched in matches.items():
        print(f"{rule_name} ({name}): {'MATCH' if matched else 'MISMATCH'}")
        if matched:
            return True
        diff_count = abs(len(result) - len(target_set)) if not matched else 0
        print(f"  Count: {len(result)} vs {len(target_set)}, Diff: {diff_count}")

    return False

print("Testing rule variations:\n")
